using System.Net;
using FluentAssertions;
using Microsoft.AspNetCore.Identity;
using Microsoft.AspNetCore.Mvc.Testing;
using Microsoft.Extensions.DependencyInjection;
using RTUB.Core.Entities;
using Xunit;

namespace RTUB.Integration.Tests;

/// <summary>
/// Integration tests for antiforgery (CSRF) protection on the browser authentication POSTs.
/// Tokens always come from the server, the way a browser gets them: the React /login reads its
/// token from GET /api/public/antiforgery-token, and so does the member shell's sign-out (api.ts signOut).
/// Never generated by the test.
/// </summary>
public class AuthAntiforgeryTests : IntegrationTestBase
{
    private const string IdentityCookieName = ".AspNetCore.Identity.Application";

    public AuthAntiforgeryTests(TestWebApplicationFactory factory) : base(factory)
    {
    }

    [Fact]
    public async Task LoginTokenEndpoint_IssuesAnUncachedFormToken()
    {
        var response = await CreateBrowserClient().GetAsync(AntiforgeryFormToken.Endpoint);

        response.StatusCode.Should().Be(HttpStatusCode.OK);
        response.Headers.CacheControl!.NoStore.Should().BeTrue("a token bound to one browser must never be cached");
        response.Headers.GetValues("Set-Cookie").Should().Contain(c => c.StartsWith(".AspNetCore.Antiforgery."),
            "the token is only valid together with the antiforgery cookie issued alongside it");
    }

    [Fact]
    public async Task LoginPost_WithoutAntiforgeryToken_IsRejected()
    {
        var password = TestSecret.NewPassword();
        var user = await CreateUserAsync("csrf-login-missing", password);
        var client = CreateBrowserClient();

        var response = await client.PostAsync("/auth/login", new FormUrlEncodedContent(
            new Dictionary<string, string>
            {
                ["Username"] = user.UserName!,
                ["Password"] = password,
                ["RememberMe"] = "false"
            }));

        response.StatusCode.Should().Be(HttpStatusCode.BadRequest);
        SetCookieHeaders(response).Should().NotContain(c => c.Contains(IdentityCookieName),
            "a rejected login must not issue a sign-in cookie");
    }

    [Fact]
    public async Task LoginPost_WithTamperedAntiforgeryToken_IsRejected()
    {
        var password = TestSecret.NewPassword();
        var user = await CreateUserAsync("csrf-login-tampered", password);
        var client = CreateBrowserClient();

        // Fetch a real token first so the antiforgery cookie is issued, then corrupt the token.
        var token = await AntiforgeryFormToken.FetchAsync(client);

        var response = await client.PostAsync("/auth/login", new FormUrlEncodedContent(
            new Dictionary<string, string>
            {
                [AntiforgeryFormToken.FieldName] = Tamper(token),
                ["Username"] = user.UserName!,
                ["Password"] = password,
                ["RememberMe"] = "false"
            }));

        response.StatusCode.Should().Be(HttpStatusCode.BadRequest);
        SetCookieHeaders(response).Should().NotContain(c => c.Contains(IdentityCookieName),
            "a rejected login must not issue a sign-in cookie");
    }

    [Fact]
    public async Task LoginPost_WithTokenFromRenderedForm_SignsUserIn()
    {
        var client = CreateBrowserClient();

        var response = await LoginThroughRenderedFormAsync(client, "csrf-login-ok");

        response.StatusCode.Should().Be(HttpStatusCode.Redirect);
        response.Headers.Location!.ToString().Should().Be("/events", "with no return URL a member lands on /events");
        SetCookieHeaders(response).Should().Contain(c => c.Contains(IdentityCookieName),
            "a valid login must issue the sign-in cookie");
    }

    [Fact]
    public async Task LogoutPost_WithoutAntiforgeryToken_IsRejected()
    {
        var client = CreateBrowserClient();

        var response = await client.PostAsync("/auth/logout", TokenlessLogoutForm());

        response.StatusCode.Should().Be(HttpStatusCode.BadRequest);
    }

    [Fact]
    public async Task LogoutPost_WhileAuthenticated_WithoutAntiforgeryToken_KeepsSessionSignedIn()
    {
        var client = CreateBrowserClient();
        await LoginThroughRenderedFormAsync(client, "csrf-logout-missing");

        var response = await client.PostAsync("/auth/logout", TokenlessLogoutForm());

        response.StatusCode.Should().Be(HttpStatusCode.BadRequest);

        // The session the React shell reads: still signed in after the rejected request.
        var me = await client.GetStringAsync("/api/account/me");
        me.Should().Contain("\"authenticated\":true", "a rejected logout must leave the session signed in");
    }

    [Fact]
    public async Task LogoutPost_WithTokenFromRenderedForm_SignsUserOut()
    {
        var client = CreateBrowserClient();
        await LoginThroughRenderedFormAsync(client, "csrf-logout-ok");

        // The token the React member shell's "Terminar sessão" fetches (api.ts signOut).
        var token = await AntiforgeryFormToken.FetchAsync(client);

        var response = await client.PostAsync("/auth/logout", new FormUrlEncodedContent(
            new Dictionary<string, string> { [AntiforgeryFormToken.FieldName] = token }));

        response.StatusCode.Should().Be(HttpStatusCode.Redirect);
        response.Headers.Location!.ToString().Should().Be("/");
        SetCookieHeaders(response).Should().Contain(
            c => c.StartsWith(IdentityCookieName + "=;", StringComparison.Ordinal),
            "a valid logout must clear the sign-in cookie");
    }

    private HttpClient CreateBrowserClient() => Factory.CreateClient(new WebApplicationFactoryClientOptions
    {
        AllowAutoRedirect = false,
        HandleCookies = true
    });

    private async Task<ApplicationUser> CreateUserAsync(string userName, string password)
    {
        using var scope = Factory.Services.CreateScope();
        var userManager = scope.ServiceProvider.GetRequiredService<UserManager<ApplicationUser>>();
        var user = new ApplicationUser
        {
            UserName = userName,
            Email = $"{userName}@test.com",
            EmailConfirmed = true,
            FirstName = "Anti",
            LastName = "Forgery",
            Nickname = userName,
            PhoneNumber = "123456789"
        };

        var result = await userManager.CreateAsync(user, password);
        result.Succeeded.Should().BeTrue();
        return user;
    }

    /// <summary>
    /// Drives the real browser flow: fetch the antiforgery token the React login uses, POST the form.
    /// The password is generated here so the create and the POST share one value that is never
    /// written down; no caller needs to know it.
    /// </summary>
    private async Task<HttpResponseMessage> LoginThroughRenderedFormAsync(
        HttpClient client, string userName)
    {
        var password = TestSecret.NewPassword();
        var user = await CreateUserAsync(userName, password);
        var token = await AntiforgeryFormToken.FetchAsync(client);

        return await client.PostAsync("/auth/login", new FormUrlEncodedContent(
            new Dictionary<string, string>
            {
                [AntiforgeryFormToken.FieldName] = token,
                ["Username"] = user.UserName!,
                ["Password"] = password,
                ["RememberMe"] = "false"
            }));
    }

    /// <summary>
    /// A logout POST body with no antiforgery token. The body is deliberately non-empty: an empty
    /// one is rejected with 400 because the request has no body at all, which would make an
    /// antiforgery test pass for the wrong reason.
    /// </summary>
    private static FormUrlEncodedContent TokenlessLogoutForm() => new(
        new Dictionary<string, string> { ["_handler"] = "LogoutForm" });

    private static IEnumerable<string> SetCookieHeaders(HttpResponseMessage response) =>
        response.Headers.TryGetValues("Set-Cookie", out var values) ? values : Array.Empty<string>();

    private static string Tamper(string token) =>
        token[..^1] + (token[^1] == 'A' ? 'B' : 'A');
}

/// <summary>
/// Antiforgery tokens the way a browser gets them: from the endpoint the React pages call (no Blazor
/// form is left to render one since task 036).
/// </summary>
internal static class AntiforgeryFormToken
{
    /// <summary>Default <c>AntiforgeryOptions.FormFieldName</c>; the app does not override it.</summary>
    internal const string FieldName = "__RequestVerificationToken";

    internal const string Endpoint = "/api/public/antiforgery-token";

    /// <summary>GET the token endpoint (which also sets the antiforgery cookie on the client).</summary>
    internal static async Task<string> FetchAsync(HttpClient client)
    {
        var response = await client.GetAsync(Endpoint);
        response.StatusCode.Should().Be(HttpStatusCode.OK);

        var body = await System.Net.Http.Json.HttpContentJsonExtensions.ReadFromJsonAsync<TokenBody>(response.Content);
        body!.FieldName.Should().Be(FieldName);
        body.Token.Should().NotBeNullOrEmpty();
        return body.Token;
    }

    private sealed record TokenBody(string FieldName, string Token);
}
